// Migration tests. The "simple" group was generated by
// `dart run drift_dev make-migrations` and checks that every upgrade path
// (1→2, and later 1→3, 2→3, ...) produces exactly the schema of the target
// version. The data test below checks that real data survives the upgrade.
import 'package:drift/drift.dart';
import 'package:drift_dev/api/migrations_native.dart';
import 'package:flutter_test/flutter_test.dart';
import 'package:money_tracker/data/db/app_database.dart';

import 'generated/schema.dart';

void main() {
  driftRuntimeOptions.dontWarnAboutMultipleDatabases = true;
  late SchemaVerifier verifier;

  setUpAll(() {
    verifier = SchemaVerifier(GeneratedHelper());
  });

  group('simple database migrations', () {
    const versions = GeneratedHelper.versions;
    for (final (i, fromVersion) in versions.indexed) {
      group('from $fromVersion', () {
        for (final toVersion in versions.skip(i + 1)) {
          test('to $toVersion', () async {
            final schema = await verifier.schemaAt(fromVersion);
            final db = AppDatabase(schema.newConnection());
            await verifier.migrateAndValidate(db, toVersion);
            await db.close();
          });
        }
      });
    }
  });

  test('v1 → v2 keeps existing data and seeds approximate rates', () async {
    // A database exactly as a v1 user would have it, with some data in it.
    final schema = await verifier.schemaAt(1);
    final raw = schema.rawDatabase;
    raw.execute('''
      INSERT INTO currencies VALUES
        ('HKD', 2, 'HK\$'), ('USD', 2, '\$'), ('EUR', 2, '€'),
        ('AUD', 2, 'A\$'), ('JPY', 0, '¥');
      INSERT INTO accounts (id, name, kind, currency, created_at, updated_at)
        VALUES ('a1', 'Cash', 'cash', 'HKD', 0, 0);
      INSERT INTO categories (id, name, kind, created_at, updated_at)
        VALUES ('c1', 'Food', 'expense', 0, 0);
      INSERT INTO transactions (id, type, occurred_on, account_id, category_id,
          amount_minor, currency, fx_rate_to_base, base_amount_minor,
          created_at, updated_at)
        VALUES ('t1', 'expense', '2026-11-05', 'a1', 'c1', 4550, 'HKD', 1, 4550, 0, 0);
    ''');

    final db = AppDatabase(schema.newConnection());
    await verifier.migrateAndValidate(db, 2);

    // Old data untouched.
    final tx = await db.select(db.transactions).getSingle();
    expect(tx.amountMinor, 4550);
    expect((await db.select(db.accounts).getSingle()).name, 'Cash');

    // New table exists and has the built-in rates.
    final rates = await db.select(db.exchangeRates).get();
    expect(rates.map((r) => r.quote), unorderedEquals(['USD', 'HKD', 'EUR', 'AUD', 'JPY']));
    expect(rates.every((r) => r.source == 'seed'), isTrue);

    await db.close();
  });
}
